"""matplotlib.backends.backend_webagg_core — webagg_core backend stub.

The shim renders every figure through plotly, so this module exists to
satisfy ``from matplotlib.backends.backend_webagg_core import
FigureCanvasWebAggCore`` imports. Saving uses plotly's native export.
"""

from matplotlib.backends._backend_helpers import (
    _make_canvas, _make_manager, _make_backend,
)


FigureCanvasWebAggCore = _make_canvas('FigureCanvasWebAggCore', 'png')
FigureManagerWebAggCore = _make_manager('FigureManagerWebAggCore')

# Aliases — every backend exposes ``FigureCanvas`` and ``FigureManager``.
FigureCanvas = FigureCanvasWebAggCore
FigureManager = FigureManagerWebAggCore

# Backend class registered with matplotlib's _Backend system.
_BackendStub = _make_backend('_BackendWebAggCore', FigureCanvas, FigureManager)
new_figure_manager = _BackendStub.new_figure_manager
draw_if_interactive = _BackendStub.draw_if_interactive
show = _BackendStub.show


